// Runtime-built first playable scene. No imported assets are required.
public class MulbiGame : MonoBehaviour
{
    [Serializable] class SaveData { public int day=1, affection=0, trust=0, fish=0, chapter=1, chanwooBond=0, kimukBond=0, kimukTrust=0; public bool met=false; }
    SaveData data; GameObject player, chanwoo, kimuk, bobber; Camera cam; Rigidbody motor; Font koreanFont;
    float yaw, pitch=14, fishingTime; bool cursorLocked, showDialog, fishing, journal, badEnding;
    int dialogueStep, currentBoy; string toast="", fishResult=""; float toastUntil;
    readonly List<string> log = new List<string>();
    string[] lines = {"야, 나 어제 그물 혼자 들었다? 별거 아니던데. 임찬우는 원래 이런 거 잘해. 찬우가 다른 남학생들 앞에서 괜히 목소리를 키웠다.","사람들이 가고 나자 찬우는 물에 젖은 손을 바지에 문질렀다. ‘아까 건… 그냥 분위기 맞춘 거야. 내가 원래 그런 애는 아닌데.’","‘이승아, 네가 옆에 있으면 다들 내가 진짜 대단한 줄 알아.’ 찬우의 웃음은 자랑과 부탁 사이에서 흔들렸다.","어장 축제 날, 찬우는 또 사람들 앞에서 허세를 부렸다. 이번엔 그가 망신당하지 않게 거짓말을 보태 달라고 눈짓했다."};
    string[] chapterMoments = {"17살 연이승은 방학 동안 아버지의 어장을 맡았다. 첫날, 임찬우는 다른 남학생들 앞에서 일부러 목소리를 키웠다.","찬우는 사람들 앞에서만 더 크게 웃었다. 이승은 그 웃음이 누구를 향하는지 보기 시작했다.","찬우가 그물에 발이 걸려 넘어질 뻔한 날, 이승은 놀리는 대신 손을 내밀었다. 그는 그 일을 아무에게도 말하지 않았다.","찬우가 허세를 부릴 때마다 주변 아이들은 웃었다. 웃음이 끝나면 찬우는 이승의 표정을 먼저 확인했다.","마을 축제 준비가 시작됐다. 찬우는 무대 위에서 어장 일을 혼자 해냈다고 자랑했고, 이승에게 사실을 맞춰 달라고 했다.","둘만 남은 방파제에서 찬우는 처음으로 목소리를 낮췄다. 그때 이승은 자기 마음보다 그의 약점을 먼저 기억했다.","축제의 연습 영상이 퍼졌다. 찬우의 과장은 모두의 농담거리가 됐고, 이승은 자신이 던진 미끼의 무게를 느꼈다.","찬우는 더 큰소리로 떠들며 아무렇지 않은 척했다. 아무도 없는 어장 창고에서만 손이 떨렸다.","‘너는 내가 어떤 사람인지 궁금한 거야, 아니면 내가 너를 좋아하는 게 좋은 거야?’ 찬우가 물었다.","이승은 대답 대신 축제 포스터를 붙였다. 찬우는 그 침묵을 허락으로 받아들였다.","축제가 가까워질수록 두 사람은 더 많은 약속을 했다. 지킬 수 없는 말들이 그물코처럼 서로를 조였다.","마지막 날, 어장엔 찬우의 낡은 낚싯대 하나만 남았다. 이승은 그가 섬을 떠난 뒤에야 진짜 대답을 생각했다."};
    string[][] choices = {new[]{"사람들 앞에서 찬우의 허세를 부추긴다.","“그물 무거웠지?” 둘만 있을 때 물어본다."},new[]{"“다들 네가 멋있다고 하던데.” 미끼를 던진다.","“애쓰는 거 알아.” 조용히 편을 들어준다."},new[]{"찬우의 자랑에 맞장구치고 더 큰 약속을 받아낸다.","그가 두려워하는 걸 다른 남학생들 앞에서 감춰준다."},new[]{"찬우 대신 거짓말해 그를 붙잡는다.","솔직히 말하라고 하고 관계를 걸어본다."}};
    string[] kimukLines = {"제방 수리 도와줄게. 대신 네가 장부 정리 좀 보여줘. 난 이런 숫자 정리하는 게 편하거든.","김욱은 찬우가 떠난 뒤에도 남아 의자를 접었다. ‘너는 사람들 마음도 장부처럼 칸칸이 나눠 적어?’","‘나도 네 어장에 들어가 있는 거야?’ 김욱은 웃으려 했지만, 대답을 기다리는 눈을 숨기진 못했다.","축제 전날, 김욱은 이승의 기록장을 돌려줬다. 찬우 이름 아래에 자기 이름이 적힌 걸 이미 봤다고 했다."};
    string[][] kimukChoices = {new[]{"“네가 있어서 일 처리가 빨라.” 곁에 붙잡아 둔다.","“고마워. 너한테는 솔직하게 말할게.”"},new[]{"그를 안심시키고 다른 약속도 받아낸다.","장부에 이름을 적은 이유를 말한다."},new[]{"“당연히 특별하지.” 그가 믿고 싶은 말을 고른다.","“모르겠어.” 처음으로 꾸미지 않고 답한다."},new[]{"찬우 앞에서 김욱의 마음을 모른 척한다.","김욱의 이름을 장부에서 지우고 그의 선택을 존중한다."}};
    void Start(){Application.targetFrameRate=60;Cursor.lockState=CursorLockMode.Locked;cursorLocked=true; data=Load();BuildWorld(); if(!data.met){ShowDialogue(0);data.met=true;Save();}}
    SaveData Load(){try{var loaded=JsonUtility.FromJson<SaveData>(PlayerPrefs.GetString("mulbi-save","{}"));return loaded==null||loaded.day<1?new SaveData():loaded;}catch{return new SaveData();}}
    void Save(){PlayerPrefs.SetString("mulbi-save",JsonUtility.ToJson(data));PlayerPrefs.Save();}
    string CurrentLine(){if(currentBoy==1){if(dialogueStep==0)return "제"+data.day+"일, 임찬우가 사람들 앞에서 목소리를 높이는 동안 현김욱은 말없이 장부의 틀린 숫자를 고쳐 놓았다.\n\n"+kimukLines[0];return kimukLines[Mathf.Clamp(dialogueStep,0,3)];}if(dialogueStep==0){int chapter=Mathf.Clamp(data.chapter-1,0,chapterMoments.Length-1);return chapterMoments[chapter]+"\n\n"+lines[0];}return lines[Mathf.Clamp(dialogueStep,0,lines.Length-1)];}
    string EndingText(){string chanwoo=data.chanwooBond>data.trust?"축제가 끝난 날 네가 보탠 거짓말이 드러났다. 사람들 앞에서 웃음거리가 된 임찬우는 섬을 떠났다.":"찬우는 축제가 끝난 날 섬을 떠났다. 네가 진실을 말할 순간마다 침묵했던 걸 알고 있었다.";string kim=data.kimukBond>data.kimukTrust?"현김욱은 장부를 네게 돌려주고 전학을 갔다. 그가 남긴 마지막 쪽지에는 이름 대신 정리된 숫자만 적혀 있었다.":"현김욱은 가족을 따라 섬을 떠났다. 둘은 끝내 서로를 좋아했는지 확인하지 못했다.";return chanwoo+" "+kim+" 남은 어장에는 빈 기록장만 놓여 있었다. 여러 사람의 마음을 관리했지만, 누구도 곁에 남지 않았다.";}
    Material Mat(Color c){var m=new Material(Shader.Find("Standard"));m.color=c;return m;}
    GameObject Cube(string n,Vector3 p,Vector3 s,Color c,Transform parent=null){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().material=Mat(c);if(parent)g.transform.SetParent(parent);return g;}
    GameObject Sphere(string n,Vector3 p,Vector3 s,Color c,Transform parent=null){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name=n;g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().material=Mat(c);if(parent)g.transform.SetParent(parent);return g;}
    void BuildWorld(){
        RenderSettings.ambientLight=new Color(.65f,.71f,.66f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.46f,.59f,.59f);RenderSettings.fogDensity=.008f;Camera.main?.gameObject.SetActive(false);
        var ground=GameObject.CreatePrimitive(PrimitiveType.Plane);ground.name="Yeonseom · shore";ground.transform.localScale=new Vector3(16,1,16);ground.GetComponent<Renderer>().material=Mat(new Color(.36f,.40f,.32f));
        var pond=GameObject.CreatePrimitive(PrimitiveType.Cube);pond.name="Fishing pond · buoyancy volume";pond.transform.position=new Vector3(0,-.48f,-8);pond.transform.localScale=new Vector3(42,.9f,34);pond.GetComponent<Renderer>().material=Mat(new Color(.16f,.39f,.42f));pond.GetComponent<Collider>().isTrigger=true;
        Cube("Pier",new Vector3(0,.18f,-1),new Vector3(4,.36f,15),new Color(.39f,.29f,.21f));for(int z=-7;z<6;z+=2)for(int x=-1;x<=1;x+=2)Cube("Pier post",new Vector3(x,.02f,z),new Vector3(.22f,.7f,.22f),new Color(.25f,.19f,.15f));
        Cube("Tackle shed",new Vector3(-9,1.3f,-1),new Vector3(7,2.6f,5),new Color(.43f,.34f,.24f));var roof=Cube("Shed roof",new Vector3(-9,2.8f,-1),new Vector3(8,.35f,6),new Color(.23f,.20f,.17f));
        for(int i=0;i<45;i++){float x=UnityEngine.Random.Range(-29,29),z=UnityEngine.Random.Range(-28,22);if(Mathf.Abs(z+8)<12&&Mathf.Abs(x)<22)continue;var trunk=GameObject.CreatePrimitive(PrimitiveType.Cylinder);trunk.transform.position=new Vector3(x,1,z);trunk.transform.localScale=new Vector3(.25f,1.1f,.25f);trunk.GetComponent<Renderer>().material=Mat(new Color(.29f,.23f,.18f));var crown=GameObject.CreatePrimitive(PrimitiveType.Capsule);crown.transform.position=new Vector3(x,2.6f,z);crown.transform.localScale=new Vector3(1.6f,1.5f,1.6f);crown.GetComponent<Renderer>().material=Mat(new Color(.15f,.27f,.21f));}
        var light=new GameObject("Late afternoon sun").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.25f;light.color=new Color(1,.83f,.64f);light.transform.rotation=Quaternion.Euler(48,-34,0);
        player=new GameObject("Yeon Iseung · 17 · player");player.transform.position=new Vector3(0,.08f,10);var capsule=player.AddComponent<CapsuleCollider>();capsule.height=1.8f;capsule.radius=.36f;capsule.center=new Vector3(0,.9f,0);motor=player.AddComponent<Rigidbody>();motor.mass=52;motor.constraints=RigidbodyConstraints.FreezeRotation;motor.interpolation=RigidbodyInterpolation.Interpolate;motor.collisionDetectionMode=CollisionDetectionMode.Continuous;var avatar=GameObject.CreatePrimitive(PrimitiveType.Capsule);avatar.name="Yeonseung · school uniform";avatar.transform.SetParent(player.transform);avatar.transform.localPosition=new Vector3(0,.88f,0);avatar.transform.localScale=new Vector3(.82f,1,.76f);avatar.GetComponent<Renderer>().material=Mat(new Color(.83f,.79f,.70f));Destroy(avatar.GetComponent<Collider>());var hair=Sphere("Yeonseung · dark hair",player.transform.position+Vector3.up*1.72f,new Vector3(.72f,.56f,.68f),new Color(.12f,.11f,.14f),player.transform);hair.transform.localPosition=new Vector3(0,1.72f,0);var ribbon=Sphere("Hair ribbon",player.transform.position+new Vector3(-.34f,1.87f,-.05f),new Vector3(.22f,.16f,.12f),new Color(.63f,.23f,.27f),player.transform);ribbon.transform.localPosition=new Vector3(-.34f,1.87f,-.05f);
        chanwoo=new GameObject("Im Chanwoo · 17 · loud show-off");chanwoo.transform.position=new Vector3(5,0,2);var cbody=GameObject.CreatePrimitive(PrimitiveType.Capsule);cbody.transform.SetParent(chanwoo.transform);cbody.transform.localPosition=new Vector3(0,1,0);cbody.GetComponent<Renderer>().material=Mat(new Color(.24f,.39f,.48f));var chead=Sphere("Chanwoo face",chanwoo.transform.position+Vector3.up*2,new Vector3(.72f,.82f,.72f),new Color(.78f,.59f,.48f),chanwoo.transform);chead.transform.localPosition=new Vector3(0,2,0);var chair=Sphere("Chanwoo hair",chanwoo.transform.position+Vector3.up*2.2f,new Vector3(.78f,.59f,.72f),new Color(.10f,.10f,.12f),chanwoo.transform);chair.transform.localPosition=new Vector3(0,2.2f,0);
        kimuk=new GameObject("Hyun Kimuk · 17 · quiet bookkeeper");kimuk.transform.position=new Vector3(-3,0,3);var kbody=GameObject.CreatePrimitive(PrimitiveType.Capsule);kbody.transform.SetParent(kimuk.transform);kbody.transform.localPosition=new Vector3(0,1,0);kbody.GetComponent<Renderer>().material=Mat(new Color(.38f,.43f,.34f));var khead=Sphere("Kimuk face",kimuk.transform.position+Vector3.up*2,new Vector3(.72f,.82f,.72f),new Color(.82f,.66f,.54f),kimuk.transform);khead.transform.localPosition=new Vector3(0,2,0);var khair=Sphere("Kimuk hair",kimuk.transform.position+Vector3.up*2.2f,new Vector3(.78f,.58f,.7f),new Color(.20f,.17f,.14f),kimuk.transform);khair.transform.localPosition=new Vector3(0,2.2f,0);kimuk.SetActive(data.day>=5);
        var cgo=new GameObject("Player camera");cgo.tag="MainCamera";cam=cgo.AddComponent<Camera>();cam.fieldOfView=68;cam.nearClipPlane=.08f;cgo.AddComponent<AudioListener>();
    }
    void Update(){if(player==null)return;if(data.day>=5&&!kimuk.activeSelf)kimuk.SetActive(true);if(Input.GetKeyDown(KeyCode.Escape)){cursorLocked=false;Cursor.lockState=CursorLockMode.None;}if(Input.GetMouseButtonDown(0)&&!showDialog&&!journal){Cursor.lockState=CursorLockMode.Locked;cursorLocked=true;}
        if(cursorLocked&&!showDialog&&!journal&&!fishing){yaw+=Input.GetAxis("Mouse X")*2.2f;pitch-=Input.GetAxis("Mouse Y")*1.5f;pitch=Mathf.Clamp(pitch,-8,55);player.transform.rotation=Quaternion.Euler(0,yaw,0);float h=(Input.GetKey(KeyCode.D)?1:0)-(Input.GetKey(KeyCode.A)?1:0),v=(Input.GetKey(KeyCode.W)?1:0)-(Input.GetKey(KeyCode.S)?1:0);Vector3 desired=(player.transform.forward*v+player.transform.right*h);if(desired.sqrMagnitude>1)desired.Normalize();Vector3 velocity=motor.velocity;Vector3 horizontal=new Vector3(velocity.x,0,velocity.z);Vector3 target=desired*4.2f;Vector3 delta=target-horizontal;motor.AddForce(new Vector3(delta.x,0,delta.z)*18f,ForceMode.Acceleration);if(Input.GetKeyDown(KeyCode.Space)&&Physics.Raycast(player.transform.position+Vector3.up*.05f,Vector3.down,.15f))motor.AddForce(Vector3.up*5f,ForceMode.VelocityChange);}
        Vector3 look=player.transform.position+Vector3.up*1.55f;Quaternion cameraRotation=Quaternion.Euler(pitch,yaw,0);cam.transform.position=look-cameraRotation*Vector3.forward*4.2f;cam.transform.rotation=cameraRotation;
        if(Input.GetKeyDown(KeyCode.E))Interact();if(fishing){fishingTime+=Time.deltaTime;if(Input.GetKeyDown(KeyCode.Space))CatchFish();if(fishingTime>9){fishing=false;fishResult="미끼만 사라졌다. 스페이스바로 찌가 빛날 때 당겨야 한다.";}}
        chanwoo.transform.rotation=Quaternion.Slerp(chanwoo.transform.rotation,Quaternion.LookRotation(player.transform.position-chanwoo.transform.position),Time.deltaTime*2);if(kimuk.activeSelf)kimuk.transform.rotation=Quaternion.Slerp(kimuk.transform.rotation,Quaternion.LookRotation(player.transform.position-kimuk.transform.position),Time.deltaTime*2);if(data.day>=30&&!badEnding){badEnding=true;showDialog=true;dialogueStep=4;cursorLocked=false;Cursor.lockState=CursorLockMode.None;}
    }
    void Interact(){if(data.day>=5&&kimuk.activeSelf&&Vector3.Distance(player.transform.position,kimuk.transform.position)<4){if(!showDialog&&!badEnding)ShowDialogue(Mathf.Min(3,(data.day-5)%4),1);return;}if(Vector3.Distance(player.transform.position,chanwoo.transform.position)<4){if(!showDialog&&!badEnding)ShowDialogue(Mathf.Min(3,(data.day-1)%4),0);return;}if(Mathf.Abs(player.transform.position.x)<4&&player.transform.position.z<5&&player.transform.position.z>-15){CastRod();return;}if(Mathf.Abs(player.transform.position.x+9)<5&&Mathf.Abs(player.transform.position.z+1)<5){journal=true;cursorLocked=false;Cursor.lockState=CursorLockMode.None;return;}Toast("임찬우 또는 현김욱에게 다가가 E를 누르세요.");}
    void CastRod(){if(fishing)return;fishing=true;fishingTime=0;fishResult="물 위에 찌가 떨어졌다. 흔들리는 순간 SPACE로 당긴다.";if(bobber)Destroy(bobber);Vector3 castPoint=player.transform.position+player.transform.forward*2.6f+Vector3.up*1.7f;bobber=GameObject.CreatePrimitive(PrimitiveType.Sphere);bobber.name="Fishing float · PhysX";bobber.transform.position=castPoint;bobber.transform.localScale=Vector3.one*.19f;bobber.GetComponent<Renderer>().material=Mat(new Color(.95f,.55f,.30f));var body=bobber.AddComponent<Rigidbody>();body.mass=.15f;body.drag=.18f;body.angularDrag=.15f;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.AddForce(player.transform.forward*4f+Vector3.up*1.2f,ForceMode.VelocityChange);bobber.AddComponent<FishingFloat>();}
    void ShowDialogue(int i,int boy=0){dialogueStep=i;currentBoy=boy;showDialog=true;cursorLocked=false;Cursor.lockState=CursorLockMode.None;}
    void Choose(int i){bool lure=i==0;if(dialogueStep<4){if(currentBoy==0){if(lure){data.affection++;data.chanwooBond++;}else data.trust++;}else{if(lure){data.affection++;data.kimukBond++;}else{data.trust++;data.kimukTrust++;}}if(dialogueStep==3){data.day++;data.chapter=Mathf.Clamp((data.day+4)/5,1,12);log.Add("제"+data.day+"일: 연이승은 임찬우와 현김욱의 마음을 각각 장부의 다른 칸에 적었다.");}showDialog=false;}Save();}
    void CatchFish(){fishing=false;float phase=(fishingTime%2.4f)/2.4f;bool bite=phase>.45f&&phase<.69f;if(bite){data.fish++;data.affection++;fishResult="은빛 붕어를 낚았다. 이승은 물고기보다 당신을 보고 있었다.";log.Add("은빛 붕어를 낚았다. 이승의 표정이 오래 기억에 남았다.");if(bobber){var f=GameObject.CreatePrimitive(PrimitiveType.Sphere);f.name="Silver crucian carp";f.transform.position=bobber.transform.position-Vector3.up*.8f;f.transform.localScale=new Vector3(.55f,.25f,.2f);f.GetComponent<Renderer>().material=Mat(new Color(.68f,.75f,.73f));hookedFish=f;Destroy(f,2.5f);Destroy(bobber,2.5f);}}else{fishResult="물결만 남았다. 다음엔 찌가 빛날 때 당겨보자.";if(bobber)Destroy(bobber,1f);}Save();Toast(fishResult);}
    void Toast(string s){toast=s;toastUntil=Time.time+3;}
    void OnGUI(){if(koreanFont==null)koreanFont=Font.CreateDynamicFontFromOSFont(new[]{"Malgun Gothic","Arial"},17);if(koreanFont!=null){GUI.skin.label.font=koreanFont;GUI.skin.button.font=koreanFont;}GUI.skin.label.fontSize=17;GUI.skin.label.normal.textColor=new Color(.94f,.91f,.82f);GUI.skin.button.fontSize=16;GUI.skin.button.normal.textColor=Color.white;GUI.Box(new Rect(0,0,Screen.width,56),"");GUI.Label(new Rect(22,12,300,36),"물비늘   ·   연이승, 17");GUI.Label(new Rect(Screen.width-390,12,370,36),$"DAY {data.day:00}   ♡ 임찬우 {data.chanwooBond} · 현김욱 {data.kimukBond}");GUI.Label(new Rect(20,75,480,62),$"오늘의 일\n{(data.day<5?"연애 어장 첫 상대, 임찬우의 허세를 읽는다":data.day<30?"임찬우와 현김욱의 마음을 동시에 관리한다":"마지막 축제에서 관계의 대가를 마주한다")}");if(!showDialog&&!journal&&!fishing)GUI.Label(new Rect(Screen.width-310,82,290,60),"WASD 이동  ·  마우스 시점\nE 대화/연애 기록 · Space 낚시");
        if(showDialog){GUI.Box(new Rect(Screen.width*.17f,Screen.height-225,Screen.width*.66f,195),"");GUI.contentColor=new Color(.9f,.77f,.52f);GUI.Label(new Rect(Screen.width*.19f,Screen.height-210,400,30),dialogueStep==4?"BAD ENDING · 빈 연애 어장":(currentBoy==0?"임찬우 · 17세":"현김욱 · 17세"));GUI.contentColor=Color.white;GUI.Label(new Rect(Screen.width*.19f,Screen.height-174,Screen.width*.62f,85),dialogueStep==4?EndingText():CurrentLine());if(dialogueStep==4){if(GUI.Button(new Rect(Screen.width*.36f,Screen.height-74,Screen.width*.28f,36),"처음으로 돌아가기")){PlayerPrefs.DeleteKey("mulbi-save");UnityEngine.SceneManagement.SceneManager.LoadScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene().buildIndex);}}else{string[] activeChoices=currentBoy==0?choices[dialogueStep]:kimukChoices[dialogueStep];for(int i=0;i<2;i++)if(GUI.Button(new Rect(Screen.width*.19f+i*Screen.width*.31f,Screen.height-86,Screen.width*.29f,42),activeChoices[i]))Choose(i);}}
        if(fishing){GUI.Box(new Rect(Screen.width*.33f,Screen.height*.47f,Screen.width*.34f,90),"낚시 · 물리 시뮬레이션");float phase=(fishingTime%2.4f)/2.4f;GUI.Label(new Rect(Screen.width*.35f,Screen.height*.51f,Screen.width*.30f,32),phase>.45f&&phase<.69f?"✦ 찌가 빛난다! SPACE ✦":"찌를 지켜보세요...");}
        if(journal){GUI.Box(new Rect(Screen.width*.25f,Screen.height*.18f,Screen.width*.5f,Screen.height*.64f),"연애 어장 관리표");GUI.Label(new Rect(Screen.width*.28f,Screen.height*.25f,Screen.width*.43f,145),$"제{data.day}일 · 연섬\n주인공 연이승, 17세\n임찬우 · 허세를 부리는 첫 상대\n  호감 {data.chanwooBond} · 신뢰 {data.trust}\n현김욱 · 5일째 합류하는 조용한 장부 담당\n  호감 {data.kimukBond} · 신뢰 {data.kimukTrust}\n낚은 물고기 {data.fish}마리 · 여러 마음을 한 장부에서 관리한다.");if(GUI.Button(new Rect(Screen.width*.31f,Screen.height*.63f,Screen.width*.28f,40),"기록을 닫는다"))journal=false;if(GUI.Button(new Rect(Screen.width*.31f,Screen.height*.70f,Screen.width*.28f,40),"오늘의 일을 마치고 잠든다")){journal=false;data.day++;data.chapter=Mathf.Clamp((data.day+4)/5,1,12);Save();Toast("새로운 아침이 찾아왔다.");}}
        if(!string.IsNullOrEmpty(toast)&&Time.time<toastUntil)GUI.Box(new Rect(Screen.width*.25f,Screen.height*.28f,Screen.width*.5f,46),toast);
    }
}

public class FishingFloat : MonoBehaviour
{
    Rigidbody body; bool inWater; float phase;
    void Awake(){body=GetComponent<Rigidbody>();phase=UnityEngine.Random.value*6.28f;}
    void OnTriggerEnter(Collider other){if(other.name.Contains("buoyancy volume"))inWater=true;}
    void OnTriggerExit(Collider other){if(other.name.Contains("buoyancy volume"))inWater=false;}
    void FixedUpdate(){if(!body||!inWater)return;float surface=-.03f;float depth=surface-transform.position.y;float force=Mathf.Clamp(depth*19f,-3f,26f);body.AddForce(Vector3.up*force,ForceMode.Acceleration);body.AddForce(Vector3.up*Mathf.Sin(Time.time*2.1f+phase)*.45f,ForceMode.Acceleration);body.AddTorque(new Vector3(Mathf.Sin(Time.time+phase),0,Mathf.Cos(Time.time*.8f+phase))*.035f,ForceMode.Acceleration);}
}
